'use strict';
const {PolicyEngine}=require('./policy-engine');
const KEY=Symbol.for('forge.policy.engine');
function engine(pool){if(!globalThis[KEY]||globalThis[KEY].pool!==pool)globalThis[KEY]={pool,engine:new PolicyEngine({pool})};return globalThis[KEY].engine;}
async function enforce(args){return engine(args.pool).evaluate(args);}
function denied(r){throw Object.assign(new Error(r.reason||'Policy denied'),{code:'POLICY_DENIED',statusCode:403,policyDecisionId:r.decisionId,policySignature:r.signature});}
function install(){if(globalThis[Symbol.for('forge.policy.boundaries.v2')])return;globalThis[Symbol.for('forge.policy.boundaries.v2')]=true;
 try{const {JobQueue}=require('../persistence/job-queue');const claim=JobQueue.prototype.claim;JobQueue.prototype.claim=async function(o={}){const j=await claim.call(this,o);if(!j?.tenant_id)return j;const r=await enforce({pool:this.pool,tenantId:j.tenant_id,subject:{type:'worker',id:o.workerId,tenantId:j.tenant_id},resource:{type:'job',id:j.id,tenantId:j.tenant_id,projectId:j.project_id},action:`runner.${j.kind}`});if(r.decision!=='ALLOW'){await this.cancel(j.id,o.workerId,r.reason).catch(()=>{});return null}return j;};}catch{}
 try{const {ProviderAdmission}=require('../admission/provider-admission');if(ProviderAdmission.prototype.acquire){const acquire=ProviderAdmission.prototype.acquire;ProviderAdmission.prototype.acquire=async function(i={}){const s=await this.scope(i.context||{});const r=await enforce({pool:this.pool,tenantId:s.tenantId,subject:{type:i.context?.workerId?'worker':'service',id:i.context?.workerId||i.context?.actor||'runtime',tenantId:s.tenantId},resource:{type:'provider',id:i.provider,tenantId:s.tenantId,projectId:s.projectId},action:`provider.${i.operation||'execute'}`});if(r.decision!=='ALLOW')denied(r);return acquire.call(this,i);};}}catch{}
 try{const {PublishService}=require('../publishing/publish-service');if(PublishService.prototype.ensureRequest){const original=PublishService.prototype.ensureRequest;PublishService.prototype.ensureRequest=async function(run,actor='worker'){const r=await enforce({pool:this.pool,tenantId:run.tenant_id,subject:{type:actor==='worker'?'worker':'operator',id:actor,tenantId:run.tenant_id},resource:{type:'release',id:run.id,tenantId:run.tenant_id,projectId:run.project_id},action:'release.publish'});if(r.decision!=='ALLOW')denied(r);return original.call(this,run,actor);};}}catch{}
 try{const {ProductionArtifactAccessGateway}=require('../storage/production-artifact-access-gateway');const original=ProductionArtifactAccessGateway.prototype._authorize;ProductionArtifactAccessGateway.prototype._authorize=async function(id,o={}){const a=await this._loadArtifact(id);if(a){const r=await enforce({pool:this.repository.db.pool,tenantId:a.tenant_id||o.tenantId,subject:{type:this.workerActors?.has(o.actor)?'worker':'user',id:o.actor,tenantId:o.tenantId||a.tenant_id},resource:{type:'artifact',id:a.id,tenantId:a.tenant_id||o.tenantId,projectId:a.project_id},action:o.action==='metadata'?'artifact.read':o.action==='stream'?'artifact.stream':'artifact.download'});if(r.decision!=='ALLOW')denied(r);}return original.call(this,id,o);};}catch{}
}
install();
module.exports={engine,enforce,install};
